(()=>{"use strict";const num=n=>Number(n).toLocaleString(typeof window<"u"&&window.CMI18n?window.CMI18n.formatLocale:"en-US",{maximumFractionDigits:2}),$=id=>document.getElementById(id);function render(){const r=parseFloat($("r").value)||0;if(r<=0){$("result").textContent="\u2014",$("chipCirc").textContent="\u2014",$("chipDia").textContent="\u2014";const vd2=$("verdict");vd2.className="verdict warn",$("verdictText").textContent="Enter a radius above zero.";return}const area=Math.PI*r*r,circ=2*Math.PI*r;$("result").textContent=num(area),$("chipCirc").textContent=num(circ),$("chipDia").textContent=num(2*r);const vd=$("verdict");vd.className="verdict",$("verdictText").textContent="A circle of radius "+num(r)+" has area "+num(area)+" and circumference "+num(circ)+"."}document.querySelectorAll("input").forEach(e=>e.addEventListener("input",render)),render()})();
